  "evt.baby.item.buffer": "Imprevisti",
  "evt.baby.ms.declare": "Comunicare la gravidanza (sanità e ente previdenziale)",
  "evt.baby.ms.daycare": "Iscriversi al nido o trovare chi accudirà il bimbo (presto!)",
  "evt.baby.ms.gear": "Acquisti grossi: passeggino, seggiolino auto, lettino",
  "evt.baby.ms.hospitalBag": "Valigia per l'ospedale e pratiche per i congedi dei genitori",
  "evt.baby.ms.birth": "Nascita 💛 (dichiarazione entro i termini di legge)",
  "evt.baby.cheer.early": "Prepararsi presto vuol dire comprare con la testa: l'usato per neonati costa spesso tre volte meno (tranne il seggiolino auto: sempre nuovo o di provenienza certa).",
  "evt.baby.cheer.onTrack": "Il nido si prepara al ritmo giusto. Non dimenticare i sostegni: i bonus per la nascita arrivano spesso PRIMA del bebè, se la domanda è presentata in tempo.",
  "evt.baby.cheer.behind": "Il budget è in ritardo: parti dall'obbligatorio (seggiolino auto) e dall'indispensabile (lettino, passeggino); il resto può aspettare o arrivare dalla lista nascita.",
  "evt.baby.cheer.lastStretch": "Ultime settimane! Valigia pronta, congedi richiesti, e lascia intatto il fondo imprevisti: i bebè hanno un calendario tutto loro.",
  "evt.funeral.label": "Funerale",
  "evt.funeral.tagline": "Prevedere con dignità, conoscere i propri diritti, evitare gli abusi.",
  "evt.funeral.tier.low": "Sobrio",
  "evt.funeral.tier.mid": "Classico",
  "evt.funeral.tier.high": "Cerimonia completa",
  "evt.funeral.item.services": "Onoranze funebri (prestazioni obbligatorie)",
  "evt.funeral.item.coffin": "Bara o urna",
  "evt.funeral.item.plot": "Concessione cimiteriale o cremazione (secondo il comune)",
  "evt.funeral.item.ceremony": "Cerimonia e raccoglimento",
  "evt.funeral.item.flowers": "Fiori, annuncio funebre",
  "evt.funeral.item.reception": "Rinfresco o pranzo di famiglia",
  "evt.funeral.item.headstone": "Lapide o targa (spesso in un secondo momento)",
  "evt.funeral.ms.quotes": "Confrontare due o tre preventivi dettagliati (gratuiti)",
  "evt.funeral.ms.aid": "Verificare gli aiuti: indennità per decesso, conto del defunto, casse e assicurazioni",
  "evt.funeral.ms.ceremony": "Cerimonia",
  "evt.funeral.cheer.early": "Prevedere significa proteggere i propri cari: un budget fatto a mente lucida evita decisioni costose prese di corsa e nel dolore.",
  "evt.funeral.cheer.onTrack": "Il preventivo dettagliato è il tuo migliore alleato: le onoranze funebri devono fornirtelo gratuitamente — chiedine più di uno, le differenze sono enormi.",
  "evt.funeral.cheer.behind": "Non farti mettere fretta: solo alcune prestazioni sono obbligatorie per legge, tutto il resto si tratta. Esistono anche aiuti (indennità per decesso, prelievo dal conto del defunto).",
  "evt.funeral.cheer.lastStretch": "Coraggio. Concentrati sull'essenziale, fatti accompagnare nelle pratiche e controlla ogni riga del preventivo finale prima di firmare.",
  "evt.party.label": "Festa / compleanno",
  "evt.party.tagline": "Una bella festa e un budget che non sfonda.",
  "evt.party.guests": "Numero di invitati",
  "evt.party.tier.low": "A casa",
  "evt.party.tier.mid": "Con sala",
  "evt.party.tier.high": "Festa in grande",
  "evt.party.style.enfant.label": "🎈 Bambini",
  "evt.party.style.enfant.tip": "In casa la spesa tipica è di circa 200 € tutto compreso. L'animatore professionista (200-300 €) è la voce decisiva: a cinque anni, i giochi organizzati da due genitori fanno lo stesso effetto.",
  "evt.party.style.adulte.label": "🥂 Adulti",
  "evt.party.style.adulte.tip": "L'aperitivo a buffet costa la metà di una cena servita e fa girare le persone. Chiedi a ciascuno di portare una bottiglia: un classico che funziona.",
  "evt.party.style.surprise.label": "🎁 A sorpresa",
  "evt.party.style.surprise.tip": "Budget segreto significa pagamenti discreti e distribuiti nel tempo. Crea l'evento nel tuo spazio personale (non in quello condiviso!) così la sorpresa resta una sorpresa.",
  "evt.party.item.food": "Cibo e bevande (a invitato)",
  "evt.party.item.venue": "Sala o location",
  "evt.party.item.cake": "Torta o torta a piani",
  "evt.party.item.decor": "Decorazioni",
  "evt.party.item.entertainment": "Animazione e musica",
