  "evt.party.ms.date": "Fissare la data e la lista degli invitati",
  "evt.party.ms.booking": "Prenotare la sala e l'animazione",
  "evt.party.ms.invites": "Inviare gli inviti",
  "evt.party.ms.shopping": "Spesa e preparativi",
  "evt.party.ms.dday": "Il gran giorno 🎉",
  "evt.party.cheer.early": "Una festa riuscita si decide con la lista degli invitati: è lei a guidare tutto il budget. Fissala per prima, il resto viene da sé.",
  "evt.party.cheer.onTrack": "Tutto fila — la festa è finanziata al ritmo giusto. Fare in casa decorazioni e torta di solito dimezza la spesa.",
  "evt.party.cheer.behind": "Piccolo ritardo nel finanziamento: taglia una voce di piacere (decorazioni, animazione) invece del numero di amici — la festa sono loro.",
  "evt.party.cheer.lastStretch": "Dirittura d'arrivo: conferma le presenze prima della spesa, eviti di sfamare venti fantasmi.",
  "evt.religious.label": "Festa religiosa o tradizionale",
  "evt.religious.tagline": "Eid, Tabaski, battesimo, comunione… messi a budget con calma e in anticipo.",
