  "evt.religious.ms.dday": "Giorno di festa ✨",
  "evt.religious.cheer.early": "Risparmiare con vari mesi di anticipo è la vera difesa contro l'impennata dei prezzi prima della festa: compri quando è ancora tutto tranquillo.",
  "evt.religious.cheer.onTrack": "Il risparmio dedicato procede bene: la festa sarà bella E senza debiti. È esattamente lo spirito giusto.",
  "evt.religious.cheer.behind": "Il finanziamento è in ritardo: meglio una festa un po' più sobria di un prestito da restituire dopo — nessuno ricorda il prezzo, tutti ricordano il momento.",
  "evt.religious.cheer.lastStretch": "Il gran giorno è vicino: gli ultimi acquisti al mercato si trattano meglio la mattina, e una lista scritta evita gli extra.",
